            vector<int> dp(n+1,0);
            dp[0]=1;
            for(int i=1;i<=n;i++)
            {
                for(int j=(i==n)?1:0;j<i;j++)
                {
                    if(dp[j] and ust.find(it.substr(j,i-j))!=ust.end())
                    {
                        dp[i]=1;
